from pathlib import Path

def find_actual_jpegs(root_dir):
    jpegs = []
    for root, dirs, files in os.walk(root_dir):
        for file in files:
            if file.lower().endswith(('.jpg', '.jpeg', '.png', '.gif')):
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'rb') as f:
                        header = f.read(4)
                        # Check for JPEG magic number (FF D8 FF)
                        if header.startswith(b'\xff\xd8\xff'):
                            jpegs.append(file_path)
                        # Check for PNG magic number (89 50 4E 47)
                        elif header.startswith(b'\x89PNG'):
                            jpegs.append(file_path)
                        elif len(header) == 1 and header == b'v':  # skip git-lfs pointer files
                            pass
                        else:
                            # Check if it's a text file (git-lfs or other)
                            try:
                                header.decode('ascii')
                            except:
                                # Binary but not recognized format
                                pass
                except:
                    pass
    return jpegs

jpegs = find_actual_jpegs('data_small')
print(f"Found {len(jpegs)} actual image files")
if jpegs:
    print(f"Sample: {jpegs[:3]}")"}

